def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A 5 on the bottom edge marks a vertical beam. Existing colored cells
    # along that beam project vertically into the blank intervals between them.
    for c in range(w):
        if g[h - 1][c] != 5:
            continue
        points = [(r, g[r][c]) for r in range(h) if g[r][c] != 0]
        for (r1, col1), (r2, col2) in zip(points, points[1:]):
            if col1 == col2:
                for r in range(r1 + 1, r2):
                    g[r][c] = col1
            else:
                mid = (r1 + r2) // 2
                for r in range(r1 + 1, mid + 1):
                    g[r][c] = col1
                for r in range(mid + 1, r2):
                    g[r][c] = col2
        # Extend the uppermost encountered color to the top.
        if points:
            r, color = points[0]
            for rr in range(r):
                if g[rr][c] == 0:
                    g[rr][c] = color
    return g
