def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    for c in range(w):
        if g[h - 1][c] != 5:
            continue

        seeds = [(r, g[r][c]) for r in range(h - 1) if g[r][c] != 0]
        if not seeds:
            continue

        # Extend the highest seed to the top.
        first_r, first_color = seeds[0]
        for r in range(first_r):
            g[r][c] = first_color

        # In each gap, extend the lower seed's color upward.
        for (upper_r, _), (lower_r, lower_color) in zip(seeds, seeds[1:]):
            for r in range(upper_r + 1, lower_r):
                g[r][c] = lower_color

        # The bottom marker extends down the remainder of its column.
        last_r = seeds[-1][0]
        for r in range(last_r + 1, h):
            g[r][c] = 5

    return g
